params.description:
属性查询条件，支持 >、<、>=、<=、<>、=、!=、and、or、()、in、between 等操作符，
详细情况请看 ALaSQL ，内部执行代码大致为 SELECT * FROM [${feature.properties}] WHERE ${where} ;
 中文文本需要加单引号 ； where条件中如果键为数字开头需使用[]包裹后使用

examples:
var conditions = {
 where: "POINTNAME = '班公错' or WQDATASOUR = '湖库'",
 location: {
 feature: {
 geometry: {
 type: 'polygon',
 coordinates: [
 [
 [9089335.567189163, 3267816.4465026017], [10038817.728498086, 4318471.435356706],
 [10341679.838613156, 1624114.5902586086], [9089335.567189163, 3267816.4465026017]
 ]
 ],
 spatialReference: { wkid: 102100 },
 },
 },
 relationship: 'contain',
 },
};
Layer.filter('湖泊河流', conditions);

